INSERT INTO public.questions (language, level, category, question_type, question_text, options, correct_answer, explanation, image_url, audio_url, points, max_plays, order_hint, is_active) VALUES
('es','B1','orthography','mcq','Elige la frase correctamente escrita.','["A ver si vienes mañana.","Haber si vienes mañana.","Haver si vienes mañana.","A ber si vienes mañana."]','A ver si vienes mañana.','"A ver" se escribe separado y con uve.',NULL,NULL,1,5,300,true),
('es','B1','orthography','mcq','Elige la frase correctamente escrita.','["No sé por qué no vino.","No se porque no vino.","No sé porqué no vino.","No se por que no vino."]','No sé por qué no vino.','"Sé" lleva tilde diacrítica y "por qué" interrogativo va separado y con tilde.',NULL,NULL,1,5,301,true),
('es','B1','orthography','mcq','¿Cuál es la palabra correctamente escrita?','["excepción","eccepción","excepcion","exepción"]','excepción','Se escribe con "xc" y lleva tilde por ser aguda terminada en n.',NULL,NULL,1,5,302,true),
('es','B1','orthography','mcq','Elige la forma correcta: Espero que no ______ a llover.','["vaya","valla","baya","balla"]','vaya','"Vaya" es del verbo ir; "valla" es una cerca y "baya" un fruto.',NULL,NULL,1,5,303,true),
('es','B2','orthography','mcq','Elige la forma correcta: No quiero café ______ té.','["sino","si no","sinó","cino"]','sino','"Sino" es la conjunción adversativa; "si no" introduce una condición.',NULL,NULL,1,5,310,true),
('es','B2','orthography','mcq','¿Cuál es la palabra correctamente escrita?','["exuberante","exhuberante","exuverante","ecsuberante"]','exuberante','Se escribe sin hache intercalada y con uve baja.',NULL,NULL,1,5,311,true),
('es','B2','orthography','mcq','¿Cuál es la palabra correctamente escrita?','["concienzudo","conciensudo","conzienzudo","concienszudo"]','concienzudo','Se escribe con "z" antes de la "u".',NULL,NULL,1,5,312,true),
('es','B2','orthography','mcq','Elige la frase correctamente escrita.','["Me preguntó qué haríamos.","Me preguntó que haríamos.","Me preguntó qué aríamos.","Me pregunto que aríamos."]','Me preguntó qué haríamos.','Interrogativa indirecta: "qué" con tilde y "haríamos" con hache.',NULL,NULL,1,5,313,true),
('es','B1','reading','mcq','Lee el texto: "Marta trabaja desde hace dos años en una agencia de viajes de Valencia. Al principio le costaba atender a los clientes extranjeros, así que decidió apuntarse a clases nocturnas de inglés. Hoy es ella quien organiza los viajes internacionales de la agencia, aunque reconoce que todavía se pone nerviosa cuando habla por teléfono." ¿Por qué se apuntó Marta a clases nocturnas?','["Porque le resultaba difícil atender a los clientes extranjeros","Porque quería cambiar de empresa","Porque su jefe se lo exigió","Porque quería viajar al extranjero"]','Porque le resultaba difícil atender a los clientes extranjeros','El texto indica la causa: le costaba atender a los clientes extranjeros.',NULL,NULL,1,5,400,true),
('es','B1','reading','mcq','Lee el texto: "Marta trabaja desde hace dos años en una agencia de viajes de Valencia. Al principio le costaba atender a los clientes extranjeros, así que decidió apuntarse a clases nocturnas de inglés. Hoy es ella quien organiza los viajes internacionales de la agencia, aunque reconoce que todavía se pone nerviosa cuando habla por teléfono." ¿Qué admite Marta actualmente?','["Que todavía se pone nerviosa al hablar por teléfono","Que ya no necesita estudiar","Que prefiere no tratar con extranjeros","Que quiere dejar la agencia"]','Que todavía se pone nerviosa al hablar por teléfono','Es la concesión que aparece al final del texto.',NULL,NULL,1,5,401,true),
('es','B1','reading','mcq','Lee el texto: "El ayuntamiento de Santa Clara ha instalado veinte bicicletas públicas en el centro. El servicio es gratuito la primera media hora y funciona con una tarjeta que se solicita por internet. Los vecinos lo han recibido bien, aunque algunos se quejan de que hay pocas estaciones en los barrios alejados." ¿Cómo se obtiene la tarjeta del servicio?','["Se solicita por internet","Se compra en el ayuntamiento","Se recoge en las estaciones","Se pide por teléfono"]','Se solicita por internet','El texto lo indica explícitamente.',NULL,NULL,1,5,402,true),
('es','B1','reading','mcq','Lee el texto: "El ayuntamiento de Santa Clara ha instalado veinte bicicletas públicas en el centro. El servicio es gratuito la primera media hora y funciona con una tarjeta que se solicita por internet. Los vecinos lo han recibido bien, aunque algunos se quejan de que hay pocas estaciones en los barrios alejados." ¿Cuál es la principal queja de algunos vecinos?','["Hay pocas estaciones en los barrios alejados","El servicio es demasiado caro","Las bicicletas están en mal estado","El horario es muy limitado"]','Hay pocas estaciones en los barrios alejados','Es la única crítica mencionada en el texto.',NULL,NULL,1,5,403,true),
('es','B2','reading','mcq','Lee el texto: "La empresa Delta ha implantado el teletrabajo tres días por semana. Según la dirección, la medida ha reducido los costes de oficina y ha mejorado la satisfacción del personal. Sin embargo, los responsables de equipo señalan que la coordinación se ha vuelto más lenta y que los empleados más jóvenes reciben menos acompañamiento que antes." ¿Cuál es la postura de los responsables de equipo?','["Reconocen inconvenientes en la coordinación y en el acompañamiento","Rechazan totalmente el teletrabajo","Piden ampliar el teletrabajo a toda la semana","Consideran que los costes han aumentado"]','Reconocen inconvenientes en la coordinación y en el acompañamiento','Señalan dos problemas concretos, sin rechazar la medida.',NULL,NULL,1,5,410,true),
('es','B2','reading','mcq','Lee el texto: "La empresa Delta ha implantado el teletrabajo tres días por semana. Según la dirección, la medida ha reducido los costes de oficina y ha mejorado la satisfacción del personal. Sin embargo, los responsables de equipo señalan que la coordinación se ha vuelto más lenta y que los empleados más jóvenes reciben menos acompañamiento que antes." ¿Qué se deduce del texto?','["Que la medida presenta ventajas y también inconvenientes","Que la medida ha fracasado por completo","Que la dirección y los responsables coinciden plenamente","Que el personal ha rechazado la medida"]','Que la medida presenta ventajas y también inconvenientes','El texto opone los beneficios señalados por la dirección a las dificultades observadas.',NULL,NULL,1,5,411,true),
('es','B2','reading','mcq','Lee el texto: "El pequeño municipio de Alcorve ha pasado de 800 a 2.300 habitantes en cinco años. La llegada de familias jóvenes se explica por el precio de la vivienda y por la mejora de la conexión a internet, que permite trabajar a distancia. El alcalde advierte, no obstante, de que la escuela y el centro de salud se han quedado pequeños." ¿Qué explica principalmente el aumento de población?','["La vivienda asequible y una mejor conexión a internet","La apertura de una gran fábrica","El turismo de verano","La construcción de un hospital"]','La vivienda asequible y una mejor conexión a internet','Son las dos causas mencionadas en el texto.',NULL,NULL,1,5,412,true),
('es','B2','reading','mcq','Lee el texto: "El pequeño municipio de Alcorve ha pasado de 800 a 2.300 habitantes en cinco años. La llegada de familias jóvenes se explica por el precio de la vivienda y por la mejora de la conexión a internet, que permite trabajar a distancia. El alcalde advierte, no obstante, de que la escuela y el centro de salud se han quedado pequeños." ¿Qué actitud muestra el alcalde?','["Satisfecho por el crecimiento pero preocupado por los servicios públicos","Totalmente pesimista","Indiferente ante el crecimiento","Crítico con las familias jóvenes"]','Satisfecho por el crecimiento pero preocupado por los servicios públicos','El conector "no obstante" introduce una advertencia, no un rechazo.',NULL,NULL,1,5,413,true);
